data.config.yaml:
{
  "_config_version": 51,
  "model": {
    "provider": "openrouter",
    "default": "nvidia/nemotron-3-ultra-550b-a55b:free",
    "base_url": "https://openrouter.ai/api/v1",
    "api_mode": "chat_completions"
  },
  "database": {
    "journal_mode": "delete"
  },
  "agent": {
    "max_turns": 5,
    "gateway_timeout": 900
  },
  "max_concurrent_sessions": 2,
  "group_sessions_per_user": true,
  "web": {
    "backend": "firecrawl",
    "search_backend": "firecrawl",
    "extract_backend": "firecrawl"
  },
  "kanban": {
    "dispatch_in_gateway": false,
    "review_dispatch": false,
    "notify_in_gateway": false,
    "auto_subscribe_on_create": false
  },
  "terminal": {
    "backend": "local",
    "cwd": "/opt/data/workspace",
    "timeout": 120,
    "home_mode": "profile"
  },
  "memory": {
    "memory_enabled": true,
    "user_profile_enabled": true,
    "memory_char_limit": 2200,
    "user_char_limit": 1800,
    "nudge_interval": 10
  },
  "compression": {
    "enabled": true
  },
  "skills": {
    "external_dirs": [
      "/opt/karem/skills"
    ],
    "creation_nudge_interval": 0
  },
  "platform_toolsets": {
    "cli": [
      "web",
      "terminal",
      "file",
      "skills",
      "todo",
      "memory",
      "session_search",
      "clarify"
    ],
    "telegram": [
      "web",
      "terminal",
      "file",
      "skills",
      "todo",
      "memory",
      "session_search",
      "clarify"
    ]
  },
  "platforms": {
    "telegram": {
      "extra": {
        "drop_pending_on_cold_boot": true,
        "disable_link_previews": true,
        "unauthorized_dm_behavior": "ignore"
      }
    }
  },
  "auxiliary": {
    "free_only": true
  }
}
